package com.yuegang.zhihui.search.application;import com.yuegang.zhihui.search.infrastructure.*;import org.springframework.beans.factory.annotation.*;import org.springframework.context.annotation.*;import org.springframework.jdbc.core.*;@Configuration(proxyBeanMethods=false)class SearchConfiguration{@Bean DoubaoEmbeddingGateway embeddingGateway(@Value("${ygh.search.embedding-base-url}")String b,@Value("${ygh.search.embedding-api-key}")String k,@Value("${ygh.search.embedding-model}")String m){return new DoubaoEmbeddingGateway(b,k,m);}@Bean HybridSearchService hybridSearchService(JdbcTemplate j,@Value("${ygh.search.elasticsearch-base-url}")String e,DoubaoEmbeddingGateway g,@Value("${ygh.search.index-alias:knowledge-active}")String a){return new HybridSearchService(j,e,g,a);}}
